s32 ExpToLevel(s32 exp) {
    s32 need;
    s32 rate;
    s32 lv;
    s32 product;

    lv = 99;
    rate = 2970;
    while (lv != 0) {
        if (lv <= 60) {
            need = (lv - 1) * (rate + 1000);
        } else {
            product = (lv - 60) * 4600;
            need = 0x28550;
            need += product;
        }
        if (exp >= need) {
            return lv;
        }
        lv--;
        rate -= 30;
    }
    return 1;
}

s32 ExpToLevel(s32 exp) {
    s32 lv;
    s32 need;

    lv = 99;
    while (lv != 0) {
        need = CalcLevelExp(lv);
        if (exp >= need) {
            return lv;
        }
        lv--;
    }
    return 1;
}

s32 ExpToLevel(s32 exp) {
    s32 lv;

    lv = 99;
    while (lv != 0) {
        if (exp >= CalcLevelExp(lv)) {
            return lv;
        }
        lv--;
    }
    return 1;
}
